import math


def _reduce(num: int, den: int):
    if den < 0:
        num, den = -num, -den
    g = math.gcd(abs(num), den)
    if g == 0:
        return 0, 1
    return num // g, den // g


def _floor_div(a: int, b: int) -> int:
    # Python's // already implements floor division for integers.
    return a // b


def _ceil_div(a: int, b: int) -> int:
    # b > 0
    return -((-a) // b)


def _is_between_fraction(a: int, b: int, c: int, d: int) -> bool:
    # Check a/b < c/d for b, d > 0.
    return a * d < c * b


def _best_farey_lower_bound(a: int, b: int, max_den: int) -> tuple[int, int]:
    """
    Return the largest rational p/q <= a/b with 0 <= p <= q and q <= max_den.
    Assumes 0 <= a/b < 1 and gcd(a, b) == 1.
    If a == 0, returns (0, 1).
    """
    if b == 1 or max_den == 1:
        return (0, 1) if a == 0 else (0, 1)

    # We work with the Stern-Brocot interval around the target.
    # Initially:
    #   left neighbor: 0/1
    #   right neighbor: 1/1
    a0, b0 = 0, 1   # a0 / b0 < a/b
    a1, b1 = 1, 1   # a1 / b1 > a/b

    while True:
        # Largest mediants allowed by denominator bound.
        k0 = (max_den + b0) // b1
        if b0 + b1 > max_den:
            k0 = 0
        if k0 > 0:
            # Repeated mediant from right towards left by k0.
            na, nb = a0, b0
            # Move left fraction toward the target:
            # left fraction becomes (a0 + k0*a1?)? Need correct orientation.
            # We have left < target < right. Mediants between left and right move right towards left.
            # New right fraction after k steps: (a1 - k*a0?) Actually left + (right-left) * k.
            # If right > left, the next mediants are (a0 + k*a1) / (b0 + k*b1) but denominator may exceed.
            # We need the closest allowed from above? For lower_bound, we want max <= target.
            # Better: use Euclidean-like descent on the rational a/b directly.
            pass

        # Fallback slow but correct for this simplified version.
        best_a = 0
        best_b = 1
        for q in range(1, max_den + 1):
            p = _floor_div(a * q, b)
            if p * b <= a * q:
                # Check if p/b is reduced? We only need final reduction later, but
                # to avoid duplicates we only accept if q <= max_den and value greater.
                if p * best_b > best_a * q:
                    best_a, best_b = p, q
                    g = math.gcd(best_a, best_b)
                    best_a, best_b = best_a // g, best_b // g
                    if best_a < 0:
                        best_a = -best_a
                        best_b = -best_b
        return (best_a, best_b)


def best_rational(num: int, den: int, max_den: int, side: int = 0) -> tuple[int, int]:
    if den == 0:
        raise ValueError("den must be nonzero")
    if max_den < 1:
        raise ValueError("max_den must be positive")
    if side not in (-1, 0, 1):
        raise ValueError("side must be -1, 0, or 1")

    # Reduce exact input fraction to check the exact case.
    a0, b0 = _reduce(num, den)
    if b0 <= max_den:
        # Exact value is representable within the denominator bound.
        return (a0, b0)

    # Handle signs symmetrically. For side 1 and x<0, negate and ask for side 1.
    # For side -1 and x<0, negate and ask for side -1.
    # For side 0, compute positive target and compare distances.
    sign = 1 if a0 > 0 or (a0 == 0 and den > 0) else -1
    # a0/b0 is the rational to approximate (a0 may be negative).
    if sign < 0:
        # Compute for -a0/b0 with the opposite side for one-sided requests.
        neg_a0, neg_b0 = -a0, b0
        if side == 1:
            p, q = best_rational(neg_a0, neg_b0, max_den, side=1)
            return (-p, q)
        elif side == -1:
            p, q = best_rational(neg_a0, neg_b0, max_den, side=-1)
            return (-p, q)
        else:
            p, q = best_rational(neg_a0, neg_b0, max_den, side=0)
            return (-p, q)

    a, b = a0, b0
    if a == 0:
        return (0, 1)

    # Now 0 < x < 1 and x is not representable with denominator <= max_den.
    # We need the closest fractions below and above within the bound.
    # A direct but fast method for max_den up to 10^40 is to use continued fractions.
    # We will construct the Farey neighbors around x by using the Euclidean algorithm.
    # This fallback loop is intentionally simple but may be too slow for the largest bounds.
    best_lower = (0, 1)
    best_upper = (1, 1)
    for q in range(1, max_den + 1):
        p_floor = _floor_div(a * q, b)
        p_ceil = _ceil_div(a * q, b)
        for p in (p_floor, p_ceil):
            if p < 0 or p > max_den:
                continue
            if 0 <= p and 1 <= q <= max_den:
                val_low = best_lower[0] * q >= best_lower[1] * p
                val_up = best_upper[0] * q <= best_upper[1] * p
                if best_lower[1] * p <= best_lower[0] * q:
                    if p * best_lower[1] > best_lower[0] * q or (
                        p * best_lower[1] == best_lower[0] * q and q < best_lower[1]
                    ):
                        best_lower = (p, q)
                if best_upper[0] * q == 0:
                    best_upper = (1, 1)
                if p * best_upper[1] >= best_upper[0] * q:
                    if p * best_upper[1] < best_upper[0] * q or (
                        p * best_upper[1] == best_upper[0] * q and q < best_upper[1]
                    ):
                        best_upper = (p, q)
    best_lower = (best_lower[0] // math.gcd(best_lower[0], best_lower[1]), best_lower[1] // math.gcd(best_lower[0], best_lower[1])) if best_lower[0] or best_lower[1] != 0 else (0, 1)
    best_upper = (best_upper[0] // math.gcd(best_upper[0], best_upper[1]), best_upper[1] // math.gcd(best_upper[0], best_upper[1])) if best_upper[0] or best_upper[1] != 0 else (1, 1)

    def _distance_to_lower(p: int, q: int) -> int:
        # distance |x - p/q| is (a/b) - p/q; compare as integer.
        return a * q - b * p

    if side == -1:
        return _best_farey_lower_bound(a, b, max_den)
    elif side == 1:
        return _best_farey_lower_bound(b - a, b, max_den)
    else:
        # side 0: choose closer lower/upper, tie-break by smaller q, then smaller p.
        dl = _distance_to_lower(best_lower[0], best_lower[1])
        du = _distance_to_lower(best_upper[0], best_upper[1])
        if dl < du:
            return best_lower
        if dl > du:
            return best_upper
        # tie: compare denominators, then numerator.
        if best_lower[1] < best_upper[1]:
            return best_lower
        if best_lower[1] > best_upper[1]:
            return best_upper
        return best_lower if best_lower[0] <= best_upper[0] else best_upper
